results.final_text:
               result[k] = '[REDACTED]'
            else:
                result[k] = redact(v)
        return result
    elif isinstance(data, (str, int, float)):
        # 只有字符串可能被误认为敏感值（如键名被当作值）
        if isinstance(data, str):
            if data.lower() in ['password', 'token', 'api_key']:
                return '[REDACTED]'
        return data
    else:
        return data
```

